        await web.ExecuteScriptAsync("GaidenKit.clearToasts();prefs.reduced=false;prefs.opaque=false;GaidenTheme.select('light');navigate('library');scrollTo(0,0)");await Task.Delay(2000);
        async Task<(double Web,double Renderer)> Run(string name,string setup){
            await web.ExecuteScriptAsync(setup);
            await web.ExecuteScriptAsync("scrollTo(0,0);window.__p7=true;window.__p7f=0;(function(){const max=Math.max(1,document.body.scrollHeight-innerHeight);const start=performance.now();function tick(t){if(!window.__p7)return;window.__p7f++;const u=((t-start)/6000)%2;scrollTo(0,max*(u<1?u:2-u));requestAnimationFrame(tick);}requestAnimationFrame(tick);})()");
            var m=await MeasureWebViewCpuAsync(4000);
            await web.ExecuteScriptAsync("window.__p7=false;scrollTo(0,0)");
            log.Add("experiment "+name+" webview="+Math.Round(m.WebViewPercent,2)+" renderer="+Math.Round(m.RendererPercent,2));
            return (m.WebViewPercent,m.RendererPercent);
        }
        var baseline=await Run("baseline","document.documentElement.dataset.opaque='false';document.querySelector('.lg-backdrop').style.display='';document.querySelectorAll('.game-card').forEach(c=>c.style.boxShadow='');");
        var sidebarOff=await Run("sidebar-off","document.querySelector('.sidebar').style.backdropFilter='none';");
        await web.ExecuteScriptAsync("document.querySelector('.sidebar').style.backdropFilter=''");
        var toolbarOff=await Run("toolbar-off","document.querySelector('.toolbar-group').style.backdropFilter='none';");
        await web.ExecuteScriptAsync("document.querySelector('.toolbar-group').style.backdropFilter=''");
        var lightBlur=await Run("light-blur","document.querySelector('.sidebar').style.backdropFilter='blur(10px) saturate(1.5)';document.querySelector('.toolbar-group').style.backdropFilter='blur(10px) saturate(1.5)';");
        await web.ExecuteScriptAsync("document.querySelector('.sidebar').style.backdropFilter='';document.querySelector('.toolbar-group').style.backdropFilter=''");
        var noGlass=await Run("no-glass","document.documentElement.dataset.opaque='true';");
        await web.ExecuteScriptAsync("document.documentElement.dataset.opaque='false'");
        var noBackdrop=await Run("no-backdrop","document.querySelector('.lg-backdrop').style.display='none';");
        await web.ExecuteScriptAsync("document.querySelector('.lg-backdrop').style.display=''");
        var noShadow=await Run("no-shadow","document.querySelectorAll('.game-card').forEach(c=>c.style.boxShadow='none');");
        await web.ExecuteScriptAsync("document.querySelectorAll('.game-card').forEach(c=>c.style.boxShadow='')");
        var noImages=await Run("no-images","document.querySelectorAll('.game-card img').forEach(i=>i.style.visibility='hidden');");
        await web.ExecuteScriptAsync("document.querySelectorAll('.game-card img').forEach(i=>i.style.visibility='')");
