        await web.ExecuteScriptAsync("document.querySelectorAll('.game-card').forEach(c=>{c.style.contentVisibility='';c.style.contain='';});");
        var plain=await Run("plain-page","document.querySelector('.app-shell').style.display='none';document.querySelector('.lg-backdrop').style.display='none';document.body.style.background='#fff';const plainDiv=document.createElement('div');plainDiv.id='plain-scroll';plainDiv.style.cssText='height:8000px;background:linear-gradient(#fff,#d8d8dc)';plainDiv.textContent='plain scroll surface';document.body.append(plainDiv);");
        var result=new JsonObject{["baseline"]=Math.Round(baseline.Web,2),["sidebarOff"]=Math.Round(sidebarOff.Web,2),["toolbarOff"]=Math.Round(toolbarOff.Web,2),["lightBlur"]=Math.Round(lightBlur.Web,2),["noGlass"]=Math.Round(noGlass.Web,2),["noBackdrop"]=Math.Round(noBackdrop.Web,2),["noShadow"]=Math.Round(noShadow.Web,2),["noImages"]=Math.Round(noImages.Web,2),["noContain"]=Math.Round(noContain.Web,2),["plain"]=Math.Round(plain.Web,2),["rendererBaseline"]=Math.Round(baseline.Renderer,2)};
        File.WriteAllText(Path.Combine(folder,"experiment.json"),result.ToJsonString(new JsonSerializerOptions{WriteIndented=true}));
