        var breakdown=new JsonArray();foreach(var entry in detailAfter){double percent=(entry.Value.Cpu-(detailBefore.TryGetValue(entry.Key,out var prior)?prior.Cpu:TimeSpan.Zero)).TotalSeconds/breakdownClock.Elapsed.TotalSeconds*100;breakdown.Add(new JsonObject{["kind"]=entry.Value.Kind,["percent"]=Math.Round(percent,2)});}
        int frames=int.Parse(await web.ExecuteScriptAsync("window.__p7=false;window.__p7f"));var scrollDiagnostics=await Diagnostics();await web.ExecuteScriptAsync("scrollTo(0,0)");
        string gpu="";try{gpu=await web.CoreWebView2.CallDevToolsProtocolMethodAsync("SystemInfo.getInfo","{}");File.WriteAllText(Path.Combine(folder,"system-info.json"),gpu);}catch(Exception){}
        var result=new JsonObject{
            ["idle"]=new JsonObject{["webviewPercent"]=Math.Round(idle.WebViewPercent,2),["rendererPercent"]=Math.Round(idle.RendererPercent,2)},["idleState"]=idleDiagnostics,
            ["minimized"]=new JsonObject{["webviewPercent"]=Math.Round(minimized.WebViewPercent,2),["rendererPercent"]=Math.Round(minimized.RendererPercent,2)},["minimizedState"]=minimizedDiagnostics,
            ["scroll"]=new JsonObject{["webviewPercent"]=Math.Round(scroll.WebViewPercent,2),["rendererPercent"]=Math.Round(scroll.RendererPercent,2),["frames"]=frames},["scrollState"]=scrollDiagnostics,["scrollBreakdown"]=breakdown};
        File.WriteAllText(Path.Combine(folder,"profile.json"),result.ToJsonString(new JsonSerializerOptions{WriteIndented=true}));
        log.Add("profile "+result.ToJsonString());
    }
    private async Task PhaseSevenCaptureAsync(string folder,List<string> log,JsonObject fixture)
