            if(name=="p7-dark-detail-hover-play"){
                string sheet=await web.ExecuteScriptAsync("(()=>{const d=document.querySelector('#detail-dialog');return !!(d&&d.open)&&d.scrollWidth<=d.clientWidth+1})()");
                if(sheet!="true")throw new InvalidOperationException("detail overflow "+sheet);
                await web.ExecuteScriptAsync("document.activeElement?.blur()");await Task.Delay(100);
            }
            string overflow=await web.ExecuteScriptAsync("document.documentElement.scrollWidth<=innerWidth+1");
            if(overflow!="true")throw new InvalidOperationException("overflow "+name+" "+overflow);
            if(hover is not null){
                string raw=await web.ExecuteScriptAsync("(()=>{const el=document.querySelector("+JsonSerializer.Serialize(hover)+");if(!el)return null;const r=el.getBoundingClientRect();return JSON.stringify({x:r.left+r.width/2,y:r.top+r.height/2});})()");
                string? value=JsonSerializer.Deserialize<string>(raw);if(value is not null){var point=JsonNode.Parse(value)!;foreach(string type in new[]{"mouseMoved"})await web.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",JsonSerializer.Serialize(new{type,x=point["x"]!.GetValue<double>(),y=point["y"]!.GetValue<double>()}));await Task.Delay(260);string hovering=await web.ExecuteScriptAsync("document.querySelector("+JsonSerializer.Serialize(hover)+").matches(':hover')");if(hovering!="true")throw new InvalidOperationException("hover "+name+" "+hovering);}
            }
            if(Environment.GetCommandLineArgs().Contains("--checks-no-captures")){log.Add(name+" assertions PASS (capture disabled)");return;}
