            using var bitmap=new Bitmap(Width,Height);using var graphics=Graphics.FromImage(bitmap);IntPtr dc=graphics.GetHdc();try{PrintWindow(Handle,dc,2);}finally{graphics.ReleaseHdc(dc);}
            using(var stream=new MemoryStream()){await web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);stream.Position=0;using var preview=Image.FromStream(stream);var origin=web.PointToScreen(Point.Empty);graphics.DrawImage(preview,new Rectangle(origin.X-Location.X,origin.Y-Location.Y,web.Width,web.Height));}
            bitmap.Save(Path.Combine(folder,name+".png"),System.Drawing.Imaging.ImageFormat.Png);log.Add(name+" captured "+width+"x"+height);
        }
        await web.ExecuteScriptAsync("window.__p7ApplyNativeSnapshot=window.applyNativeSnapshot;window.__p7ShowTrackerState=window.showTrackerState;window.applyNativeSnapshot=()=>{};window.showTrackerState=()=>{}");
        string common="GaidenKit.clearToasts();document.querySelectorAll('dialog[open]').forEach(d=>d.close());window.__p7ApplyNativeSnapshot("+fixture.ToJsonString()+");prefs.reduced=false;prefs.opaque=false;window.gaidenCoverState={enabled:true,pending:[],available:[...new Set(games.map(g=>Number(g.steam?.appId)).filter(Boolean))]};modelMedia.failedSteamCovers.clear();window.__p7ShowTrackerState({text:'Ожидание игры',name:'Hades',seconds:5432,active:true});GaidenUI.moduleState('features').sortMode='recent';";
        Size=new Size(1280,800);WindowState=FormWindowState.Normal;Show();Activate();BringToFront();await Task.Delay(600);
        await Capture("p7-light-library-posters",common+"GaidenTheme.select('light');navigate('home');navigate('library');scrollTo(0,0)",null);
        await Capture("p7-dark-library-tiles",common+"window.gaidenCoverState={enabled:false,pending:[],available:[]};GaidenTheme.select('dark');navigate('home');navigate('library');scrollTo(0,0)",null);
        await Capture("p7-light-stats",common+"GaidenTheme.select('light');GaidenUI.moduleState('statistics').period='week';navigate('stats');scrollTo(0,0)",null);
        await Capture("p7-light-sessions",common+"GaidenTheme.select('light');GaidenUI.moduleState('sessions').sessionLimit=30;navigate('sessions');scrollTo(0,0)",null);
        await Capture("p7-dark-home",common+"GaidenTheme.select('dark');navigate('home');scrollTo(0,0)",null);
        await Capture("p7-dark-settings",common+"GaidenTheme.select('dark');navigate('settings');document.querySelectorAll('.settings-group').forEach(d=>d.open=false);document.querySelector('.settings-group')?.setAttribute('open','');scrollTo(0,0)",null);
        await Capture("p7-light-library-820",common+"GaidenTheme.select('light');navigate('home');navigate('library');scrollTo(0,0)",null,820,600);
        await Capture("p7-dark-detail-hover-play",common+"GaidenTheme.select('dark');navigate('library');const g=games.find(x=>x.launchAvailable&&x.steam)||games[0];openDetail(g.id)",".detail-play");
